defmodule InfluxElixir.Contract.SQLCatalogCases do
  @moduledoc "Case tables of the SQL aggregate, syntax and catalog contract, `{kind, text, expected}`, each read from InfluxDB 3 Core. See `InfluxElixir.Contract.SQLScalar` for what a kind means."

  @doc "Aggregate expressions, HAVING, implicit aliases, grouping and empty groups."
  @spec aggregates() :: [tuple()]
  def aggregates do
    [
      {:raw, "SELECT host, count(*) AS c FROM main GROUP BY host HAVING c > 3 ORDER BY host", :ok,
       [%{"c" => 4, "host" => "h0"}, %{"c" => 4, "host" => "h1"}, %{"c" => 4, "host" => "h2"}]},
      {:raw, "SELECT host, count(*) AS c FROM main GROUP BY host HAVING c > 4 ORDER BY host", :ok,
       []},
      {:raw, "SELECT host, count(*) c FROM main GROUP BY host HAVING c > 3 ORDER BY c, host", :ok,
       [%{"c" => 4, "host" => "h0"}, %{"c" => 4, "host" => "h1"}, %{"c" => 4, "host" => "h2"}]},
      {:raw,
       "SELECT host, sum(n) AS total FROM main GROUP BY host HAVING total > 10 ORDER BY host",
       :ok,
       [
         %{"host" => "h0", "total" => 18},
         %{"host" => "h1", "total" => 22},
         %{"host" => "h2", "total" => 21}
       ]},
      {:raw,
       "SELECT host, sum(n) AS total FROM main GROUP BY host HAVING total > 10 AND host = 'h1'",
       :ok, [%{"host" => "h1", "total" => 22}]},
      {:raw,
       "SELECT host, sum(n) AS total FROM main GROUP BY host HAVING total > 10 OR host = 'h0' ORDER BY host",
       :ok,
       [
         %{"host" => "h0", "total" => 18},
         %{"host" => "h1", "total" => 22},
         %{"host" => "h2", "total" => 21}
       ]},
      {:raw, "SELECT host, sum(n) + 1 AS t FROM main GROUP BY host HAVING t > 10 ORDER BY host",
       :ok,
       [%{"host" => "h0", "t" => 19}, %{"host" => "h1", "t" => 23}, %{"host" => "h2", "t" => 22}]},
      {:raw, "SELECT host, count(*) AS c FROM main GROUP BY host HAVING c + 1 > 4 ORDER BY host",
       :ok,
       [%{"c" => 4, "host" => "h0"}, %{"c" => 4, "host" => "h1"}, %{"c" => 4, "host" => "h2"}]},
      {:raw,
       "SELECT host, count(*) AS c FROM main GROUP BY host HAVING c IS NOT NULL ORDER BY host",
       :ok,
       [%{"c" => 4, "host" => "h0"}, %{"c" => 4, "host" => "h1"}, %{"c" => 4, "host" => "h2"}]},
      {:raw,
       "SELECT host, count(*) AS c FROM main GROUP BY host HAVING c BETWEEN 3 AND 4 ORDER BY host",
       :ok,
       [%{"c" => 4, "host" => "h0"}, %{"c" => 4, "host" => "h1"}, %{"c" => 4, "host" => "h2"}]},
      {:raw,
       "SELECT host, count(*) AS c FROM main GROUP BY host HAVING c IN (4, 5) ORDER BY host", :ok,
       [%{"c" => 4, "host" => "h0"}, %{"c" => 4, "host" => "h1"}, %{"c" => 4, "host" => "h2"}]},
      {:raw, "SELECT host, count(*) AS c FROM main GROUP BY host HAVING NOT c > 3 ORDER BY host",
       :ok, []},
      {:raw, "SELECT host, count(*) AS c FROM main GROUP BY host HAVING sum(n) > c ORDER BY host",
       :ok,
       [%{"c" => 4, "host" => "h0"}, %{"c" => 4, "host" => "h1"}, %{"c" => 4, "host" => "h2"}]},
      {:raw,
       "SELECT host, max(n) AS m, min(n) AS l FROM main GROUP BY host HAVING m > 8 AND l >= 0 ORDER BY host",
       :ok,
       [
         %{"host" => "h0", "l" => 0, "m" => 9},
         %{"host" => "h1", "l" => 1, "m" => 10},
         %{"host" => "h2", "l" => 2, "m" => 11}
       ]},
      {:raw, "SELECT host AS h, count(*) AS c FROM main GROUP BY host HAVING h = 'h1'", :ok,
       [%{"c" => 4, "h" => "h1"}]},
      {:raw, "SELECT host AS h, count(*) AS c FROM main GROUP BY host HAVING h = 'h1' AND c > 3",
       :ok, [%{"c" => 4, "h" => "h1"}]},
      {:raw,
       "SELECT upper(host) AS u, count(*) AS c FROM main GROUP BY upper(host) HAVING u = 'H1'",
       :ok, [%{"c" => 4, "u" => "H1"}]},
      {:raw, "SELECT count(*) AS c FROM main HAVING c > 3", :ok, [%{"c" => 12}]},
      {:raw, "SELECT count(*) AS c FROM main HAVING c > 30", :ok, []},
      {:raw,
       "SELECT host, count(*) AS \"C\" FROM main GROUP BY host HAVING \"C\" > 3 ORDER BY host",
       :ok,
       [%{"C" => 4, "host" => "h0"}, %{"C" => 4, "host" => "h1"}, %{"C" => 4, "host" => "h2"}]},
      {:raw, "SELECT host, count(*) AS C FROM main GROUP BY host HAVING C > 3 ORDER BY host", :ok,
       [%{"c" => 4, "host" => "h0"}, %{"c" => 4, "host" => "h1"}, %{"c" => 4, "host" => "h2"}]},
      {:raw, "SELECT host, sum(n) AS s FROM main GROUP BY host HAVING s > 10", :error, 400,
       "Error during planning: Column in HAVING must be in GROUP BY or an aggregate function: While expanding wildcard, column \"main.s\" must appear in the GROUP BY clause or must be part of an aggregate function, currently only \"main.host, sum(main.n)\" appears in the SELECT clause satisfies this requirement"},
      {:raw, "SELECT host, count(*) AS n FROM main GROUP BY host HAVING n > 3", :error, 400,
       "Error during planning: Column in HAVING must be in GROUP BY or an aggregate function: While expanding wildcard, column \"main.n\" must appear in the GROUP BY clause or must be part of an aggregate function, currently only \"main.host, count(Int64(1))\" appears in the SELECT clause satisfies this requirement"},
      {:raw, "SELECT host AS having FROM main ORDER BY time LIMIT 2", :ok,
       [%{"having" => "h0"}, %{"having" => "h1"}]},
      {:raw, "SELECT host AS \"having\" FROM main ORDER BY time LIMIT 2", :ok,
       [%{"having" => "h0"}, %{"having" => "h1"}]},
      {:raw, "SELECT host AS HAVING FROM main ORDER BY time LIMIT 2", :ok,
       [%{"having" => "h0"}, %{"having" => "h1"}]},
      {:raw, "SELECT host AS limit FROM main ORDER BY time LIMIT 2", :ok,
       [%{"limit" => "h0"}, %{"limit" => "h1"}]},
      {:raw, "SELECT host AS offset FROM main ORDER BY time LIMIT 2", :ok,
       [%{"offset" => "h0"}, %{"offset" => "h1"}]},
      {:raw, "SELECT host AS group FROM main ORDER BY time LIMIT 2", :ok,
       [%{"group" => "h0"}, %{"group" => "h1"}]},
      {:raw, "SELECT host AS order FROM main ORDER BY time LIMIT 2", :ok,
       [%{"order" => "h0"}, %{"order" => "h1"}]},
      {:raw, "SELECT host AS where FROM main WHERE n = 1", :ok, [%{"where" => "h1"}]},
      {:raw, "SELECT host AS from FROM main WHERE n = 1", :ok, [%{"from" => "h1"}]},
      {:raw, "SELECT host AS select FROM main WHERE n = 1", :ok, [%{"select" => "h1"}]},
      {:raw, "SELECT host AS union FROM main WHERE n = 1", :ok, [%{"union" => "h1"}]},
      {:raw, "SELECT host AS join FROM main WHERE n = 1", :ok, [%{"join" => "h1"}]},
      {:raw, "SELECT host AS left FROM main WHERE n = 1", :ok, [%{"left" => "h1"}]},
      {:raw, "SELECT host AS right FROM main WHERE n = 1", :ok, [%{"right" => "h1"}]},
      {:raw, "SELECT host AS on FROM main WHERE n = 1", :ok, [%{"on" => "h1"}]},
      {:raw, "SELECT host AS using FROM main WHERE n = 1", :ok, [%{"using" => "h1"}]},
      {:raw, "SELECT count(*) AS having FROM main", :ok, [%{"having" => 12}]},
      {:raw, "SELECT host, count(*) AS having FROM main GROUP BY host ORDER BY host", :ok,
       [
         %{"having" => 4, "host" => "h0"},
         %{"having" => 4, "host" => "h1"},
         %{"having" => 4, "host" => "h2"}
       ]},
      {:raw,
       "SELECT host, count(*) AS c FROM main GROUP BY host HAVING c > 3 ORDER BY host LIMIT 1",
       :ok, [%{"c" => 4, "host" => "h0"}]},
      {:raw, "SELECT host, sum(n) AS total FROM main GROUP BY host HAVING total > 21", :ok,
       [%{"host" => "h1", "total" => 22}]},
      {:raw,
       "SELECT host, sum(n) AS total FROM main GROUP BY host HAVING total > 18 AND total < 22",
       :ok, [%{"host" => "h2", "total" => 21}]},
      {:raw,
       "SELECT host, sum(n) AS total FROM main GROUP BY host HAVING total + 1 > 22 ORDER BY total DESC",
       :ok, [%{"host" => "h1", "total" => 22}]},
      {:raw,
       "SELECT host, sum(n) AS total FROM main GROUP BY host HAVING total IN (18, 21) ORDER BY host",
       :ok, [%{"host" => "h0", "total" => 18}, %{"host" => "h2", "total" => 21}]},
      {:raw,
       "SELECT host, sum(n) AS total FROM main GROUP BY host HAVING NOT total > 18 ORDER BY host",
       :ok, [%{"host" => "h0", "total" => 18}]},
      {:raw, "SELECT host, sum(n) + 1 AS t FROM main GROUP BY host HAVING t > 22 ORDER BY host",
       :ok, [%{"host" => "h1", "t" => 23}]},
      {:raw,
       "SELECT host, sum(n) AS total, count(n) AS k FROM main GROUP BY host HAVING total > 18 AND k > 3 ORDER BY host",
       :ok, [%{"host" => "h1", "k" => 4, "total" => 22}]},
      {:raw, "SELECT host, sum(n) AS s FROM main GROUP BY host HAVING sum(n) > 10 ORDER BY host",
       :ok,
       [%{"host" => "h0", "s" => 18}, %{"host" => "h1", "s" => 22}, %{"host" => "h2", "s" => 21}]},
      {:raw, "SELECT host, sum(n) FROM main GROUP BY host HAVING sum(n) > 10 ORDER BY host", :ok,
