      {:raw,
       "SELECT host, count(*) AS c FROM main GROUP BY host HAVING count(*) = 4 AND sum(n) > 10 ORDER BY host",
       :ok,
       [%{"c" => 4, "host" => "h0"}, %{"c" => 4, "host" => "h1"}, %{"c" => 4, "host" => "h2"}]},
      {:raw,
       "SELECT host, count(*) AS c FROM main GROUP BY host HAVING count(*) = 4 OR sum(n) > 100 ORDER BY host",
       :ok,
       [%{"c" => 4, "host" => "h0"}, %{"c" => 4, "host" => "h1"}, %{"c" => 4, "host" => "h2"}]},
      {:raw,
       "SELECT host, count(*) AS c FROM main GROUP BY host HAVING NOT count(*) = 5 ORDER BY host",
       :ok,
       [%{"c" => 4, "host" => "h0"}, %{"c" => 4, "host" => "h1"}, %{"c" => 4, "host" => "h2"}]},
      {:raw,
