       :ok, [%{"a" => 6.75, "host" => "h0"}, %{"a" => 7.5, "host" => "h1"}]},
      {:raw,
       "SELECT host, max(n) AS m FROM main GROUP BY host HAVING max(n) IN (9, 10, 11) ORDER BY host",
       :ok,
       [%{"host" => "h0", "m" => 9}, %{"host" => "h1", "m" => 10}, %{"host" => "h2", "m" => 11}]},
      {:raw,
