      {:raw,
       "SELECT host, sum(n) AS s FROM main GROUP BY host HAVING sum(n) / count(n) >= 5 ORDER BY host",
       :ok, [%{"host" => "h1", "s" => 22}, %{"host" => "h2", "s" => 21}]},
      {:raw, "SELECT host, sum(n) AS s FROM main GROUP BY host HAVING host = 'h1'", :ok,
       [%{"host" => "h1", "s" => 22}]},
      {:raw, "SELECT host, sum(n) AS s FROM main GROUP BY host HAVING host = 'h1' AND sum(n) > 1",
       :ok, [%{"host" => "h1", "s" => 22}]},
