       405,
       "This feature is not implemented: Physical plan does not support logical expression AggregateFunction(AggregateFunction { func: AggregateUDF { inner: Count { name: \"count\", signature: Signature { type_signature: OneOf([VariadicAny, Nullary]), volatility: Immutable, parameter_names: None } } }, params: AggregateFunctionParams { args: [Literal(Int64(1), None)], distinct: false, filter: None, order_by: [], null_treatment: None } })"},
      {:raw, "SELECT n AS a, n AS a FROM main WHERE n < 3", :error, 400,
       "Error during planning: Projections require unique expression names but the expression \"main.n AS a\" at position 0 and \"main.n AS a\" at position 1 have the same name. Consider aliasing (\"AS\") one of them."},
      {:raw, "SELECT n a, n a FROM main WHERE n < 3", :error, 400,
       "Error during planning: Projections require unique expression names but the expression \"main.n AS a\" at position 0 and \"main.n AS a\" at position 1 have the same name. Consider aliasing (\"AS\") one of them."},
      {:raw, "SELECT n, n FROM main WHERE n < 3", :error, 400,
       "Error during planning: Projections require unique expression names but the expression \"main.n\" at position 0 and \"main.n\" at position 1 have the same name. Consider aliasing (\"AS\") one of them."},
      {:raw, "SELECT *, n + 1 AS p FROM main WHERE n = 1", :ok,
       [
         %{
           "b" => false,
           "host" => "h1",
