  @doc "Statements the engine's parser reads, and those it refuses with a parser error."
  @spec syntax() :: [tuple()]
  def syntax do
    [
      {:raw, "SELECT f * 1e10 AS r FROM mext ORDER BY time", :ok,
       [%{"r" => 25_000_000_000.0}, %{"r" => -5_000_000_000.0}, %{"r" => nil}]},
      {:raw, "SELECT f * 2 AS f FROM mext ORDER BY time", :ok,
       [%{"f" => 5.0}, %{"f" => -1.0}, %{"f" => 2.0e300}]},
      {:raw, "SELECT host, f * 1e300 AS g, i * 1 AS k FROM mext ORDER BY time", :ok,
       [
         %{"g" => 2.5e300, "host" => "a", "k" => -3},
         %{"g" => -5.0e299, "host" => "b", "k" => 9_223_372_036_854_775_807},
         %{"g" => nil, "host" => "a", "k" => 0}
       ]},
      {:raw, "SELECT f + f AS r, f * f AS q FROM mext ORDER BY time", :ok,
       [%{"q" => 6.25, "r" => 5.0}, %{"q" => 0.25, "r" => -1.0}, %{"q" => nil, "r" => 2.0e300}]},
      {:raw, "SELECT host FROM mext WHERE f > 9223372036854775807 ORDER BY time", :ok,
       [%{"host" => "a"}]},
      {:raw, "SELECT host FROM mext WHERE i = 9223372036854775807", :ok, [%{"host" => "b"}]},
      {:raw, "SELECT host FROM mext WHERE i < 9223372036854775807 ORDER BY time", :ok,
       [%{"host" => "a"}, %{"host" => "a"}]},
      {:raw, "SELECT host FROM mext WHERE i <= 9223372036854775807 ORDER BY time", :ok,
       [%{"host" => "a"}, %{"host" => "b"}, %{"host" => "a"}]},
      {:raw, "SELECT host FROM mext WHERE i > 9223372036854775807", :ok, []},
      {:raw, "SELECT n FROM main WHERE time > 9223372036854775807", :error, 400,
       "type_coercion\ncaused by\nError during planning: Cannot infer common argument type for comparison operation Timestamp(ns) > Int64"},
      {:raw, "SELECT n FROM main WHERE time < 9223372036854775807", :error, 400,
       "type_coercion\ncaused by\nError during planning: Cannot infer common argument type for comparison operation Timestamp(ns) < Int64"},
      {:raw, "SELECT n FROM main WHERE time >= -9223372036854775808", :error, 400,
       "type_coercion\ncaused by\nError during planning: Cannot infer common argument type for comparison operation Timestamp(ns) >= Int64"},
      {:raw, "SELECT 1_000", :ok, [%{"_000" => 1}]},
      {:raw, "SELECT 1e", :ok, [%{"e" => 1}]},
      {:raw, "SELECT 1a", :ok, [%{"a" => 1}]},
      {:raw, "SELECT 0b1", :ok, [%{"b1" => 0}]},
      {:raw, "SELECT 1_000_000", :ok, [%{"_000_000" => 1}]},
      {:raw, "SELECT 1.5e", :ok, [%{"e" => 1.5}]},
      {:raw, "SELECT 1.5abc AS x", :error, 400,
       "SQL error: ParserError(\"Expected: end of statement, found: AS at Line: 1, Column: 15\")"},
      {:raw, "SELECT 10e2", :ok, [%{"Float64(1000)" => 1000.0}]},
      {:raw, "SELECT 1e+", :error, 400,
       "SQL error: ParserError(\"Expected: end of statement, found: + at Line: 1, Column: 10\")"},
      {:raw, "SELECT 2.5_1", :ok, [%{"_1" => 2.5}]},
      {:raw, "SELECT n FROM main WHERE n = 1_0", :error, 400,
       "SQL error: ParserError(\"Expected: end of statement, found: _0 at Line: 1, Column: 31\")"},
      {:raw, "SELECT host left FROM main WHERE n = 1", :ok, [%{"left" => "h1"}]},
      {:raw, "SELECT host right FROM main WHERE n = 1", :ok, [%{"right" => "h1"}]},
      {:raw, "SELECT host full, n inner FROM main WHERE n = 1", :ok,
       [%{"full" => "h1", "inner" => 1}]},
      {:raw, "SELECT host format FROM main WHERE n = 1", :ok, [%{"format" => "h1"}]},
      {:raw, "SELECT host window FROM main WHERE n = 1", :ok, [%{"window" => "h1"}]},
      {:raw, "SELECT host pivot FROM main WHERE n = 1", :ok, [%{"pivot" => "h1"}]},
      {:raw, "SELECT host set FROM main WHERE n = 1", :ok, [%{"set" => "h1"}]},
      {:raw, "SELECT host global FROM main WHERE n = 1", :ok, [%{"global" => "h1"}]},
      {:raw, "SELECT left('hello', 2) AS l, right('hello', 2) AS r", :ok,
       [%{"l" => "he", "r" => "lo"}]},
      {:raw, "SELECT left('hello', 2), right('hello', 2)", :ok,
       [%{"left(Utf8(\"hello\"),Int64(2))" => "he", "right(Utf8(\"hello\"),Int64(2))" => "lo"}]},
      {:raw, "SELECT left(host, 1), right(host, 1) FROM main WHERE n = 1", :ok,
       [%{"left(main.host,Int64(1))" => "h", "right(main.host,Int64(1))" => "1"}]},
      {:raw, "SELECT count(*", :error, 400,
