      {:raw, "SELECT sum(", :error, 400,
       "SQL error: ParserError(\"Expected: an expression, found: EOF\")"},
      {:raw, "SELECT 5 div 2", :error, 400,
       "SQL error: ParserError(\"No infix parser for token Word(Word { value: \\\"div\\\", quote_style: None, keyword: DIV }) at Line: 1, Column: 10\")"},
      {:raw, "SELECT 5 DIV 2", :error, 400,
       "SQL error: ParserError(\"No infix parser for token Word(Word { value: \\\"DIV\\\", quote_style: None, keyword: DIV }) at Line: 1, Column: 10\")"},
      {:raw, "SELECT 5 div", :error, 400,
       "SQL error: ParserError(\"No infix parser for token Word(Word { value: \\\"div\\\", quote_style: None, keyword: DIV }) at Line: 1, Column: 10\")"},
      {:raw, "SELECT n FROM main WHERE n div 2 = 1", :error, 400,
       "SQL error: ParserError(\"No infix parser for token Word(Word { value: \\\"div\\\", quote_style: None, keyword: DIV }) at Line: 1, Column: 28\")"},
      {:raw, "SELECT 1 // 2", :error, 405,
