      {:raw, "SELECT interval '1 2' day to hour", :error, 405,
       "This feature is not implemented: Unsupported Interval Expression with last_field Some(Hour)"},
      {:raw, "SELECT interval '1' day to second", :error, 405,
       "This feature is not implemented: Unsupported Interval Expression with last_field Some(Second)"},
      {:raw, "SELECT interval '1' year to year", :error, 405,
