  @doc "Statements the engine's parser reads, and those it refuses with a parser error. Local may refuse these by name."
  @spec syntax_refusable() :: [tuple()]
  def syntax_refusable do
    [
      {:raw, "SELECT count(*, 1) FROM main", :error, 405,
       "This feature is not implemented: Physical plan does not support logical expression Wildcard { qualifier: None, options: WildcardOptions { ilike: None, exclude: None, except: None, replace: None, rename: None } }"},
      {:raw, "SELECT n // 2 FROM main", :error, 405,
       "This feature is not implemented: Operator DIV is not yet supported"},
      {:raw, "SELECT 'a' ~~ 'a'", :ok, [%{"Utf8(\"a\") ~~ Utf8(\"a\")" => true}]},
      {:raw, "SELECT 'a' ~~* 'A'", :ok, [%{"Utf8(\"a\") ~~* Utf8(\"A\")" => true}]},
      {:raw, "SELECT 'a' !~~ 'a'", :ok, [%{"Utf8(\"a\") !~~ Utf8(\"a\")" => false}]},
      {:raw, "SELECT 'a' !~~* 'b'", :ok, [%{"Utf8(\"a\") !~~* Utf8(\"b\")" => true}]},
      {:raw, "SELECT s ~~ 's%' FROM main WHERE n = 1", :ok,
       [%{"main.s ~~ Utf8(\"s%\")" => true}]},
      {:raw, "SELECT current_time IS NOT NULL", :ok, [%{"current_time() IS NOT NULL" => true}]},
      {:raw, "SELECT current_date IS NOT NULL", :ok, [%{"current_date() IS NOT NULL" => true}]},
      {:raw, "SELECT current_timestamp IS NOT NULL", :ok,
       [%{"current_timestamp() IS NOT NULL" => true}]},
      {:raw, "SELECT current_time() IS NOT NULL", :ok, [%{"current_time() IS NOT NULL" => true}]},
      {:raw, "SELECT timestamp '2020-01-01 00:00:00'", :ok,
       [%{"Utf8(\"2020-01-01 00:00:00\")" => ~U[2020-01-01 00:00:00.000000Z]}]},
      {:raw, "SELECT timestamp with time zone '2020-01-01 00:00:00'", :ok,
       [%{"Utf8(\"2020-01-01 00:00:00\")" => ~U[2020-01-01 00:00:00.000000Z]}]},
      {:raw, "SELECT timestamp without time zone '2020-01-01 00:00:00'", :ok,
       [%{"Utf8(\"2020-01-01 00:00:00\")" => ~U[2020-01-01 00:00:00.000000Z]}]},
      {:raw, "SELECT timestamp(3) '2020-01-01 00:00:00'", :ok,
       [%{"Utf8(\"2020-01-01 00:00:00\")" => ~U[2020-01-01 00:00:00.000000Z]}]},
      {:raw, "SELECT timestamp(3) with time zone '2020-01-01'", :ok,
       [%{"Utf8(\"2020-01-01\")" => ~U[2020-01-01 00:00:00.000000Z]}]},
      {:raw, "SELECT timestamptz '2020-01-01'", :ok,
       [%{"Utf8(\"2020-01-01\")" => ~U[2020-01-01 00:00:00.000000Z]}]},
      {:raw, "SELECT date '2020-01-01'", :ok, [%{"Utf8(\"2020-01-01\")" => "2020-01-01"}]},
      {:raw, "SELECT time '10:00:00'", :ok, [%{"Utf8(\"10:00:00\")" => "10:00:00"}]},
      {:raw, "SELECT time with time zone '10:00:00'", :error, 405,
       "This feature is not implemented: Unsupported SQL type TIME WITH TIME ZONE"},
      {:raw, "SELECT datetime '2020-01-01 00:00:00'", :error, 405,
       "This feature is not implemented: Unsupported SQL type DATETIME"},
      {:raw, "SELECT time(3) '10:00:00'", :error, 405,
       "This feature is not implemented: Unsupported SQL type TIME(3)"},
      {:raw,
       "SELECT n FROM main WHERE time > timestamp with time zone '2023-11-14 22:13:25' AND n = 1",
       :ok, [%{"n" => 1}]},
      {:raw, "SELECT time - time AS d FROM main WHERE n = 1", :ok, [%{"d" => "P0D"}]},
      {:raw, "SELECT max(time) - min(time) AS d FROM main", :ok, [%{"d" => "PT330S"}]},
      {:raw, "SELECT count(*) AS c FROM main WHERE time - time = interval '0'", :ok,
       [%{"c" => 12}]},
      {:raw, "SELECT time - interval '1 second' AS t FROM main WHERE n = 1", :ok,
       [%{"t" => ~U[2023-11-14 22:13:49.000000Z]}]},
      {:raw, "SELECT host on FROM main WHERE n = 1", :ok, [%{"on" => "h1"}]},
      {:raw, "SELECT host join FROM main WHERE n = 1", :ok, [%{"join" => "h1"}]},
      {:raw, "SELECT v FROM main WHERE n IN (1 == 1)", :error, 400,
       "type_coercion\ncaused by\nError during planning: Can not find compatible types to compare Int64 with [Boolean]"},
      {:raw, "SELECT n <=> 1 AS r FROM main ORDER BY time", :ok,
       [
